function() {
  // PATH 1: Stape Shopify app pushes user_data.new_customer (usually boolean or string)
  var v = {{dlv - user_data.new_customer}};
  if (v !== undefined && v !== null && v !== '') {
    return normalize(v);
  }

  // PATH 2: Root-level new_customer (fallback for custom configurations)
  v = {{dlv - new_customer}};
  if (v !== undefined && v !== null && v !== '') {
    return normalize(v);
  }

  // NO DATA AVAILABLE:
  // Per your rule: any unknown / missing value should be treated as NEW customer.
  return true;

  // Return false ONLY when we are certain it's returning.
  function normalize(x) {
    // Explicit booleans / numeric forms
    if (x === false || x === 0 || x === '0') return false;
    if (x === true || x === 1 || x === '1') return true;

    // Common string forms
    if (typeof x === 'string') {
      var s = x.trim().toLowerCase();
      if (['false','f','no','n','0','return','returning'].indexOf(s) !== -1) return false;
      if (['true','t','yes','y','1','new'].indexOf(s) !== -1) return true;
    }

    // Anything else -> NEW
    return true;
  }
}

function() {
  var val = {{js - is_new_customer}};
  // Per your rule: only confirmed returning should be "false"; everything else is "true"
  if (val === false) return 'false';
  return 'true';
}

